#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_head; /* offset of oldest byte */
    size_t   tail;  /* offset where next write goes      */
    size_t   count; /* bytes currently stored               */
};

ringbuf_t *rb_create(size_t capacity) {
    if (capacity == 0) return NULL;
    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)           return NULL;
    uint8_t *buf = calloc(capacity, sizeof(uint8_t));
    if (!buf) { free(rb); return NULL; }
    rb->buf          = buf;
    rb->capacity     = capacity;
    rb->head         = 0;
    rb->tail         = 0;
    rb->count        = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb) {
    if (!rb) return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len) {
    if (!rb || !data || len == 0) return 0;
    if (rb->count == rb->capacity) return 0;
    size_t free_space = rb->capacity - rb->count;
    size_t n = len < free_space ? len : free_space;
    /* copy first segment up to end of buffer */
    size_t first_segment_end = rb->capacity - rb->tail;
    size_t first_part       = first_segment_end > n ? n       : first_segment_end;
    memcpy(rb->buf + rb->tail, data, first_part);
    if (first_part < n) {
        /* wrap around */
        memcpy(rb->buf, data + first_part, n - first_part);
    }
    rb->tail = (rb->tail + n) % rb->capacity;
    rb->count += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0) return 0;
    if (rb->count == 0)          return 0;
    size_t n = len < rb->count ? len : rb->count;
    memcpy(out, rb->buf + rb->head, n);
    /* handle wrap when copying tail portion */
    rb->head = (rb->head + n) % rb->capacity;
    rb->count -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0) return 0;
    if (rb->count == 0)          return 0;
    /* Temporarily advance tail so we can use a simple forward copy */
    size_t saved_tail  = rb->tail;
    size_t saved_count = rb->count;
    /* Peek from head for up to n bytes without modifying state */
    size_t n           = len < rb->count ? len : rb->count;
    if (save_head + n <= rb->capacity) { memcpy(out, rb->buf + rb->head, n); }
    else  {
        size_t first_part = rb->capacity - rb->head;
        memcpy(out, rb->buf + rb->head, first_part);
        memcpy(out + first_part, rb->buf, n - first_part);
    }
    rb->head += n;               /* advance head by `n` for wrap */
    rb->count -= n;
    return n;
}

size_t rb_size(const ringbuf_t *rb) {
    if (!rb) return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb) {
    if (!rb) return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb) {
    if (!rb) return;
    rb->head     = 0;
    rb->tail     = 0;
    rb->count    = 0;
}

